<script setup lang="ts">import{ref}from'vue';import{PhPath,PhX}from'@phosphor-icons/vue';import DependencyGraph from'../components/DependencyGraph.vue';import SummaryStrip from'../components/SummaryStrip.vue';import{useAnalysis}from'../composables/useAnalysis';const a=useAnalysis();const showCycles=ref(true);const mobilePanel=ref(false);function select(id:string){a.selectedId.value=id;mobilePanel.value=true}</script>
<template><template v-if="a.data.value"><SummaryStrip :data="a.data.value"/><section class="workspace"><div class="map-stage"><div class="stage-head"><div><h1>系统依赖蓝图</h1><p>拖动节点重排结构，滚轮缩放，选择模块查看证据。</p></div><button class="toggle" :aria-pressed="showCycles" @click="showCycles=!showCycles"><span></span>循环路径</button></div><DependencyGraph :nodes="a.data.value.nodes" :edges="a.data.value.edges" :selected="a.selectedId.value" :show-cycles="showCycles" @select="select"/><div class="legend"><span><i class="normal"></i>稳定模块</span><span><i class="risk"></i>风险模块</span><span><i class="cycle"></i>循环依赖</span></div></div><aside class="inspector" :class="{open:mobilePanel}" aria-label="模块检查台"><button class="close-inspector" aria-label="关闭检查台" @click="mobilePanel=false"><PhX :size="20"/></button><template v-if="a.selected.value"><div class="inspector-title"><span>{{a.selected.value.domain}}</span><h2>{{a.selected.value.label}}</h2><p>{{a.selected.value.language}} · {{a.selected.value.loc.toLocaleString()}} LOC</p></div><div class="risk-score"><span>综合风险</span><strong>{{a.selected.value.risk}}</strong><small>/ 100</small></div><div class="measure-list"><div><span>圈复杂度</span><b>{{a.selected.value.complexity}}</b><progress :value="a.selected.value.complexity" max="100"></progress></div><div><span>近30天变更</span><b>{{a.selected.value.churn}}</b><progress :value="a.selected.value.churn" max="80"></progress></div><div><span>测试覆盖率</span><b>{{a.selected.value.coverage}}%</b><progress class="inverse" :value="a.selected.value.coverage" max="100"></progress></div><div><span>连接度</span><b>{{a.selected.value.degree}}</b><progress :value="a.selected.value.degree" max="10"></progress></div></div><article v-if="a.selectedInsight.value" class="diagnosis"><PhPath :size="20"/><div><h3>{{a.selectedInsight.value.title}}</h3><p>{{a.selectedInsight.value.detail}}</p></div></article><div class="connections"><h3>直接依赖 <span>{{a.related.value.length}}</span></h3><button v-for="edge in a.related.value" :key="edge.source+edge.target" @click="select(edge.source===a.selectedId.value?edge.target:edge.source)"><code>{{edge.source}}</code><span>→</span><code>{{edge.target}}</code><b>{{edge.coupling}}</b></button></div></template></aside></section></template></template>
